package bench

import (
	"encoding/base64"
	"net/url"
	"strings"
)

// redactSecrets removes any occurrence of the given secret values from s,
// replacing each with a placeholder. Errors built from authenticated HTTP
// response bodies (the OAuth token exchange, the entiredb info/refs probe) are
// surfaced to the GUI over SSE and persisted in the result doc, so scrub the
// credential that was in scope for that request out of the text first — a
// misbehaving endpoint that echoes the token back can't then leak it.
func redactSecrets(s string, secrets ...string) string {
	for _, sec := range secrets {
		if sec != "" {
			s = strings.ReplaceAll(s, sec, "[redacted]")
		}
	}
	return s
}

// authForms returns every representation a basic-auth credential took on the
// wire, so all of them can be scrubbed from an echoed response: the raw
// secret, its URL-encoded form (as it appears in a form body or URL), and the
// complete `Authorization: Basic` value base64(user:pass). Redacting only the
// literal secret would let an endpoint that echoes the authorization header —
// or any encoded rendition of the request — leak the credential verbatim.
func authForms(user, pass string) []string {
	return []string{
		pass,
		url.QueryEscape(pass),
		base64.StdEncoding.EncodeToString([]byte(user + ":" + pass)),
	}
}
package bench

import (
	"encoding/base64"
	"fmt"
	"testing"
)

func TestRedactSecrets(t *testing.T) {
	body := `{"error":"invalid_grant","echoed":"eyJ-subject-token"}`
	got := redactSecrets(body, "eyJ-subject-token")
	if got == body {
		t.Fatalf("secret not redacted: %q", got)
	}
	if contains(got, "eyJ-subject-token") {
		t.Errorf("secret still present: %q", got)
	}
	// Empty secrets are ignored (an unset password must not blank the message).
	if out := redactSecrets("plain text", "", ""); out != "plain text" {
		t.Errorf("empty secrets altered the message: %q", out)
	}
}

// A misbehaving endpoint can echo the credential in any wire representation it
// saw, not just the literal secret: the base64 Basic authorization value, or
// the URL-encoded form-body rendition. authForms must cover them all.
func TestAuthFormsCoverEncodedRepresentations(t *testing.T) {
	user, pass := "token", "s3cr&t+pass"
	basic := base64.StdEncoding.EncodeToString([]byte(user + ":" + pass))
	body := fmt.Sprintf(`{"authorization":"Basic %s","form":"subject_token=s3cr%%26t%%2Bpass","raw":"%s"}`, basic, pass)
	got := redactSecrets(body, authForms(user, pass)...)
	for _, leak := range []string{pass, basic, "s3cr%26t%2Bpass"} {
		if contains(got, leak) {
			t.Errorf("credential representation %q survived redaction: %q", leak, got)
		}
	}
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}
